#!/usr/bin/env node

import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const outputDir = path.join(root, "db", "postgres");
const outputPath = path.join(outputDir, "001_initial_schema.sql");

const migration = `-- AI PDM PostgreSQL / Supabase initial schema
-- Generated by scripts/generate-postgres-migration.mjs
-- Keep application-generated TEXT ids to preserve compatibility with the current SQLite data model.

BEGIN;

CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY,
  display_name TEXT NOT NULL,
  email TEXT UNIQUE,
  password_hash TEXT,
  role TEXT NOT NULL CHECK (role IN ('Engineer', 'R&D Manager', 'Admin')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS system_settings (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by TEXT REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS items (
  id TEXT PRIMARY KEY,
  part_number TEXT NOT NULL UNIQUE,
  part_name TEXT NOT NULL,
  current_revision TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS submissions (
  id TEXT PRIMARY KEY,
  item_id TEXT NOT NULL REFERENCES items(id),
  drawing_number TEXT NOT NULL,
  revision TEXT NOT NULL,
  material TEXT NOT NULL,
  surface_finish TEXT NOT NULL,
  document_type TEXT NOT NULL,
  change_description TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('Pending', 'Releasing', 'Released', 'Rejected', 'ReleaseFailed', 'Obsolete')),
  submitted_by TEXT NOT NULL REFERENCES users(id),
  approval_required INTEGER NOT NULL DEFAULT 1 CHECK (approval_required IN (1, 2)),
  released_at TIMESTAMPTZ,
  rejected_at TIMESTAMPTZ,
  reject_reason TEXT,
  release_error TEXT,
  superseded_by_submission_id TEXT REFERENCES submissions(id),
  obsolete_at TIMESTAMPTZ,
  obsolete_by TEXT REFERENCES users(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (drawing_number, revision)
);

CREATE TABLE IF NOT EXISTS submission_files (
  id TEXT PRIMARY KEY,
  submission_id TEXT NOT NULL REFERENCES submissions(id) ON DELETE CASCADE,
  file_role TEXT NOT NULL CHECK (file_role IN ('sldprt', 'sldasm', 'slddrw', 'pdf', 'dwg', 'other')),
  original_filename TEXT NOT NULL,
  local_path TEXT NOT NULL,
  gdrive_file_id TEXT,
  gdrive_status TEXT NOT NULL DEFAULT 'none' CHECK (gdrive_status IN ('none', 'uploading', 'uploaded', 'failed', 'moved')),
  sha256 TEXT NOT NULL,
  file_size BIGINT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (submission_id, file_role, original_filename)
);

CREATE TABLE IF NOT EXISTS approval_steps (
  id TEXT PRIMARY KEY,
  submission_id TEXT NOT NULL REFERENCES submissions(id) ON DELETE CASCADE,
  reviewer_id TEXT NOT NULL REFERENCES users(id),
  sequence_no INTEGER NOT NULL DEFAULT 1,
  decision TEXT NOT NULL CHECK (decision IN ('Approved', 'Rejected')),
  comment TEXT,
  decided_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (submission_id, reviewer_id, sequence_no)
);

CREATE TABLE IF NOT EXISTS approval_matrix_requirements (
  id TEXT PRIMARY KEY,
  submission_id TEXT NOT NULL REFERENCES submissions(id) ON DELETE CASCADE,
  required_role TEXT NOT NULL CHECK (required_role IN ('R&D Manager', 'Admin')),
  min_count INTEGER NOT NULL DEFAULT 1 CHECK (min_count BETWEEN 1 AND 3),
  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'satisfied', 'waived')),
  created_by TEXT NOT NULL REFERENCES users(id),
  decided_by TEXT REFERENCES users(id),
  decision_comment TEXT,
  decided_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (submission_id, required_role)
);

CREATE TABLE IF NOT EXISTS audit_logs (
  id TEXT PRIMARY KEY,
  submission_id TEXT REFERENCES submissions(id) ON DELETE SET NULL,
  actor_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  action TEXT NOT NULL,
  detail_json JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS llm_conversations (
  id TEXT PRIMARY KEY,
  user_id TEXT REFERENCES users(id),
  title TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS llm_messages (
  id TEXT PRIMARY KEY,
  conversation_id TEXT NOT NULL REFERENCES llm_conversations(id) ON DELETE CASCADE,
  role TEXT NOT NULL CHECK (role IN ('user', 'assistant', 'system')),
  content TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_submissions_status_created_at
  ON submissions(status, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_submission_files_submission_id
  ON submission_files(submission_id);

CREATE INDEX IF NOT EXISTS idx_audit_logs_submission_id
  ON audit_logs(submission_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_submissions_item_id
  ON submissions(item_id);

CREATE INDEX IF NOT EXISTS idx_submissions_submitted_by
  ON submissions(submitted_by);

CREATE INDEX IF NOT EXISTS idx_approval_steps_submission_id
  ON approval_steps(submission_id);

CREATE INDEX IF NOT EXISTS idx_approval_matrix_submission_id
  ON approval_matrix_requirements(submission_id, status, required_role);

CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_users_updated_at ON users;
CREATE TRIGGER trg_users_updated_at
BEFORE UPDATE ON users
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

DROP TRIGGER IF EXISTS trg_items_updated_at ON items;
CREATE TRIGGER trg_items_updated_at
BEFORE UPDATE ON items
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

DROP TRIGGER IF EXISTS trg_submissions_updated_at ON submissions;
CREATE TRIGGER trg_submissions_updated_at
BEFORE UPDATE ON submissions
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

DROP TRIGGER IF EXISTS trg_llm_conversations_updated_at ON llm_conversations;
CREATE TRIGGER trg_llm_conversations_updated_at
BEFORE UPDATE ON llm_conversations
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

COMMIT;
`;

fs.mkdirSync(outputDir, { recursive: true });
fs.writeFileSync(outputPath, migration, "utf8");

console.log(JSON.stringify({
  generated: path.relative(root, outputPath).replaceAll(path.sep, "/"),
  bytes: Buffer.byteLength(migration, "utf8")
}, null, 2));
